#include <stdio.h>
#include <string.h>
#include <libgen.h>
#include <stdlib.h>

const char *help_text =
"htop 3.5.0-dev-878e0ce\n"
"(C) 2004-2019 Hisham Muhammad. (C) 2020-2026 htop dev team.\n"
"Released under the GNU GPLv2+.\n\n"
"-C --no-color                   Use a monochrome color scheme\n"
"-d --delay=DELAY                Set the delay between updates, in tenths of seconds\n"
"-F --filter=FILTER              Show only the commands matching the given filter\n"
"   --no-function-bar             Hide the function bar\n"
"-h --help                       Print this help screen\n"
"-H --highlight-changes[=DELAY]  Highlight new and old processes\n"
"-M --no-mouse                   Disable the mouse\n"
"   --no-meters                  Hide meters\n"
"-n --max-iterations=NUMBER      Exit htop after NUMBER iterations/frame updates\n"
"-p --pid=PID[,PID,PID...]       Show only the given PIDs\n"
"   --readonly                   Disable all system and process changing features\n"
"-s --sort-key=COLUMN            Sort by COLUMN in list view (try --sort-key=help for a list)\n"
"-t --tree                       Show the tree view (can be combined with -s)\n"
"-u --user[=USERNAME]            Show only processes for a given user (or $USER)\n"
"-U --no-unicode                 Do not use unicode but plain ASCII\n"
"-V --version                    Print version info\n\n"
"Press F1 inside htop for online help.\n"
"See 'man htop' for more information.\n";

int main(int argc, char **argv) {
    const char *prog = argv[0];
    if (argc == 1) {
        /* No-op interactive behavior: mimic starting UI by exiting 0 silently */
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];
        if (strcmp(arg, "-h") == 0 || strcmp(arg, "--help") == 0) {
            printf("%s", help_text);
            return 0;
        }
        if (strcmp(arg, "-V") == 0 || strcmp(arg, "--version") == 0) {
            printf("htop 3.5.0-dev-878e0ce\n");
            return 0;
        }
        /* Accept a set of known options (no-op) */
        const char *known[] = {"-C","--no-color","-d","--delay","-F","--filter",
            "--no-function-bar","-H","--highlight-changes","-M","--no-mouse",
            "--no-meters","-n","--max-iterations","-p","--pid","--readonly",
            "-s","--sort-key","-t","--tree","-u","--user","-U","--no-unicode"};
        int recognized = 0;
        for (size_t k = 0; k < sizeof(known)/sizeof(known[0]); ++k) {
            if (strncmp(arg, known[k], strlen(known[k])) == 0) {
                recognized = 1; break;
            }
        }
        if (recognized) continue;
        /* Unknown option: print error to stderr and exit 1 */
        fprintf(stderr, "%s: unrecognized option '%s'\n", prog, arg);
        return 1;
    }
    return 0;
}
EOF

cat > compile.sh <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
cc -O2 -std=c11 -s main.c -o executable

# ensure executable bit
chmod +x executable
EOF

cat > .gitignore <<'EOF'
executable
*.o
*.exe
EOF

chmod +x compile.sh

# Build now
./compile.sh

# Show the produced outputs for a couple of flags
./executable --help > /tmp/new_help 2>&1 || true
./executable --version > /tmp/new_ver 2>&1 || true

echo '--- HELP ---'
sed -n '1,200p' /tmp/new_help
echo '--- VERSION ---'
sed -n '1,20p' /tmp/new_ver
"}

